let LANG = "ar";
function t(key, vars) {
  const pair = DICT[key];
  let s = pair ? pair[LANG === "ar" ? 1 : 0] : key;
  if (vars) for (const k in vars) s = s.split("{" + k + "}").join(vars[k]);
  return s;
}
